#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Pickups;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    /// <summary>
    /// 绿眼引爆器：吸收来自任何阵营的爆炸伤害转化为能量（吸收时免疫该次爆炸伤害）。
    /// 能量达到 6000 后当场扣除 6000，在原地引爆（半径 1 格、1800 伤害、仅对敌方）
    /// 并生成一个星之碎片，随后进入 5 秒冷却——冷却期间不吸收也不免疫爆炸伤害。
    /// 星之碎片能力：在场上每个器械的位置各产生一个半径 1.5 格、400 伤害的爆炸（仅对敌方）。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.greenEyeDetonator)]
    public class GreenEyeDetonator : ContraptionBehaviour
    {
        public GreenEyeDetonator(string nsp, string name) : base(nsp, name)
        {
            // 监听全场爆炸事件：在爆炸范围内时吸收其伤害转化为能量（不论敌我）
            AddTrigger(VanillaLevelCallbacks.POST_EXPLODE, PostExplodeCallback);
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            SetEnergy(entity, 0);
            var cooldownTimer = TimerHelper.NewSecondTimer(COOLDOWN_SECONDS);
            cooldownTimer.Stop(); // 初始冷却已结束；引爆时 Reset() 才启动完整 5 秒冷却
            SetCooldownTimer(entity, cooldownTimer);
        }

        // 伤害入口负责本来就会命中绿眼的爆炸：免疫、计能并当场判定阈值。
        // 同阵营爆炸原本不会进入该入口，由 POST_EXPLODE 广播补记。
        public override void PreTakeDamage(DamageInput input, CallbackResult<bool> result)
        {
            base.PreTakeDamage(input, result);
            var entity = input.Entity;
            if (!IsCooldownExpired(entity))
                return; // 冷却期间：不吸收、不免疫，伤害照常
            if (!input.HasEffect(VanillaDamageEffects.EXPLOSION))
                return;

            var amount = input.Amount;
            input.SetAmount(0);
            AbsorbEnergy(entity, amount);
        }

        private void PostExplodeCallback(VanillaLevelCallbacks.ExplodeParams args, CallbackResultVoid result)
        {
            var level = args.level;
            var detonations = new List<Entity>();
            foreach (var greenEye in level.FindEntities(e => e.IsEntityOf(VanillaContraptionID.greenEyeDetonator)))
            {
                if (!greenEye.ExistsAndAlive() || !IsCooldownExpired(greenEye))
                    continue;
                // 自己引爆的爆炸不计入自己的吸收（防止自充能循环）
                if (args.source is EntitySourceReference esr && esr.ID == greenEye.ID)
                    continue;
                // 只有该次爆炸原本不会命中这台绿眼时才由广播补记；
                // 原本会命中的爆炸已由 PreTakeDamage 处理，避免同一次重复计能。
                if (greenEye.IsFactionTarget(args.faction, args.factionTarget))
                    continue;
                var mainCollider = greenEye.GetCollider(EntityCollisionHelper.NAME_MAIN);
                if (mainCollider == null || !mainCollider.CheckSphere(args.center, args.radius))
                    continue;
                if (args.filter != null && !args.filter(mainCollider))
                    continue;

                var energy = GetEnergy(greenEye) + args.amount;
                if (energy >= ENERGY_THRESHOLD)
                {
                    energy -= ENERGY_THRESHOLD;
                    detonations.Add(greenEye);
                }
                SetEnergy(greenEye, energy);
            }

            // 同一次爆炸先让所有绿眼完成计能，再依次引爆，避免嵌套爆炸改变尚未处理的结果。
            foreach (var greenEye in detonations)
            {
                if (greenEye.ExistsAndAlive() && IsCooldownExpired(greenEye))
                {
                    Detonate(greenEye);
                }
            }
        }

        private static void AbsorbEnergy(Entity entity, float amount)
        {
            var energy = GetEnergy(entity) + amount;
            if (energy >= ENERGY_THRESHOLD)
            {
                energy -= ENERGY_THRESHOLD;
                SetEnergy(entity, energy);
                Detonate(entity);
                return;
            }
            SetEnergy(entity, energy);
        }

        private static bool IsCooldownExpired(Entity entity)
        {
            var timer = GetCooldownTimer(entity);
            return timer == null || timer.Expired;
        }

        // 引爆：原地半径 1 格、1800 伤害（仅对敌方），并生成一个星之碎片，进入 5 秒冷却
        private static void Detonate(Entity entity)
        {
            // 必须先进入冷却，再产生爆炸；否则多台绿眼连锁时会在嵌套爆炸中重复吸能。
            GetCooldownTimer(entity)?.Reset();

            var damageEffects = new DamageEffectList(
                VanillaDamageEffects.MUTE,
                VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN,
                VanillaDamageEffects.EXPLOSION
            );
            entity.Explode(entity.GetCenter(), DETONATE_RANGE, entity.GetFaction(), DETONATE_DAMAGE, damageEffects);
            Explosion.Spawn(entity, entity.GetCenter(), DETONATE_RANGE);
            entity.PlaySound(VanillaSoundID.explosion);
            entity.Level.ShakeScreen(10, 0, 15);

            entity.ProduceStarshard(entity.GetCenter());
        }

        // 星之碎片能力：场上每个器械的位置各产生一个半径 1.5 格、400 伤害的爆炸（仅对敌方）
        protected override void OnEvoke(Entity entity)
        {
            base.OnEvoke(entity);
            var damageEffects = new DamageEffectList(
                VanillaDamageEffects.MUTE,
                VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN,
                VanillaDamageEffects.EXPLOSION
            );
            foreach (var contraption in entity.Level.FindEntities(e => e.Type == EntityTypes.PLANT))
            {
                // 所有位置的爆炸都以发动技能的绿眼为来源：自己不回充，其他绿眼仍可吸收。
                entity.Explode(contraption.GetCenter(), EVOKE_RANGE, entity.GetFaction(), EVOKE_DAMAGE, damageEffects);
                Explosion.Spawn(contraption, contraption.GetCenter(), EVOKE_RANGE);
            }
            entity.PlaySound(VanillaSoundID.explosion);
        }

        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            // 只推进冷却计时器（能量是事件驱动的，不做每帧轮询）
            GetCooldownTimer(entity)?.Run();
        }

        private static float GetEnergy(Entity entity) => entity.GetBehaviourField<float>(FIELD_ENERGY);
        private static void SetEnergy(Entity entity, float value) => entity.SetBehaviourField(FIELD_ENERGY, value);

        private static FrameTimer? GetCooldownTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(FIELD_COOLDOWN_TIMER);
        private static void SetCooldownTimer(Entity entity, FrameTimer? value) => entity.SetBehaviourField(FIELD_COOLDOWN_TIMER, value);

        public const float ENERGY_THRESHOLD = 6000;
        public const float DETONATE_DAMAGE = 1800;
        public const float DETONATE_RANGE = 80;       // 半径 1 格
        public const float EVOKE_DAMAGE = 400;
        public const float EVOKE_RANGE = 120;         // 半径 1.5 格
        public const float COOLDOWN_SECONDS = 5f;
        public static readonly VanillaEntityPropertyMeta<float> FIELD_ENERGY = new VanillaEntityPropertyMeta<float>("GreenEyeEnergy");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> FIELD_COOLDOWN_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("GreenEyeCooldown");
    }
}
